import SwiftUI

// Generated by scripts/sync-ios-palette.py from design/palette.json.
enum VipiColorRole:String,CaseIterable {
    case canvas
    case surface
    case incoming
    case outgoing
    case ink
    case secondary
    case outgoingInk = "outgoing_ink"
    case outgoingSecondary = "outgoing_secondary"
    case action
    case onAction = "on_action"
    case read
    case outgoingRead = "outgoing_read"
    case failed
    case outgoingFailed = "outgoing_failed"
    case focus
    case outgoingFocus = "outgoing_focus"
    case outline
    case separator
    case practiceFill = "practice_fill"
    case practiceInk = "practice_ink"
    case spokenFill = "spoken_fill"
    case spokenInk = "spoken_ink"
    case subdued
    case incomingEdge = "incoming_edge"
    case outgoingEdge = "outgoing_edge"
}

/// Opaque sRGB roles; native traits choose appearance and increased contrast.
enum VipiPalette {
    private static let roles:[VipiColorRole:[UInt32]] = [
        .canvas:[0xFFF8EF,0x221B22,0xFFF8EF,0x181317],
        .surface:[0xFFFDF8,0x30252C,0xFFFDF8,0x30252C],
        .incoming:[0xEBDDD2,0x382B36,0xEBDDD2,0x382B36],
        .outgoing:[0xF4BAAA,0x754756,0xF8C9B7,0x48252E],
        .ink:[0x352233,0xF9ECE4,0x2B1627,0xFFF9F1],
        .secondary:[0x6D5263,0xD2BDBF,0x493043,0xEFE0D2],
        .outgoingInk:[0x412335,0xFFF0E8,0x34172A,0xFFEDDE],
        .outgoingSecondary:[0x624052,0xF1D7D8,0x55243C,0xF9E7D7],
        .action:[0x873852,0xF3ABAB,0x552239,0xF3ABAB],
        .onAction:[0xFFF4E9,0x422333,0xFFF4E9,0x422333],
        .read:[0x883352,0xF4B6B2,0x552239,0xF4B6B2],
        .outgoingRead:[0x733046,0xFFD6A9,0x552239,0xFFE4AC],
        .failed:[0xA1283A,0xFFB9A9,0x761719,0xFFB9A9],
        .outgoingFailed:[0x73142D,0xFFC8BC,0x55151B,0xFFD9CD],
        .focus:[0x8C405E,0xF5B6B7,0x552239,0xF5B6B7],
        .outgoingFocus:[0x762843,0xFFDAAF,0x552239,0xFFDAAF],
        .outline:[0x987B81,0xBCA5A5,0x493043,0xE0CABB],
        .separator:[0xE3D4C9,0x54434C,0xE3D4C9,0x54434C],
        .practiceFill:[0xF6DB8D,0x60502D,0xF6DB8D,0x60502D],
        .practiceInk:[0x56380C,0xFFE5A6,0x56380C,0xFFE5A6],
        .spokenFill:[0x64334E,0xF5BAA0,0x64334E,0xF5BAA0],
        .spokenInk:[0xFFF1DD,0x46232B,0xFFF1DD,0x46232B],
        .subdued:[0xEEDFD9,0x44323C,0xEEDFD9,0x44323C],
        .incomingEdge:[0xBCA69C,0x54434C,0x947A6E,0x54434C],
        .outgoingEdge:[0xC38779,0x54434C,0xA66B60,0x54434C],
    ]
    static func uiColor(_ role:VipiColorRole) -> UIColor {
        let values = roles[role]!
        return UIColor { traits in
            let dark = traits.userInterfaceStyle == .dark,high = traits.accessibilityContrast == .high
            let hex = values[(high ? 2:0)+(dark ? 1:0)]
            return UIColor(red:CGFloat((hex>>16)&255)/255,green:CGFloat((hex>>8)&255)/255,blue:CGFloat(hex&255)/255,alpha:1)
        }
    }
    static func color(_ role:VipiColorRole) -> Color { Color(uiColor:uiColor(role)) }
    static func avatar(_ slot:Int) -> Color {
        precondition((0..<4).contains(slot))
        let light:[UInt32] = [0xFAD2AF,0xE4D4E6,0xD8DCB4,0xF3C3C3]
        let dark:[UInt32] = [0x5C4233,0x4F3E52,0x434832,0x5E3C45]
        return Color(uiColor:UIColor { traits in
            let hex = (traits.userInterfaceStyle == .dark ? dark:light)[slot]
            return UIColor(red:CGFloat((hex>>16)&255)/255,green:CGFloat((hex>>8)&255)/255,blue:CGFloat(hex&255)/255,alpha:1)
        })
    }
}

private struct OutgoingMessageKey:EnvironmentKey { static let defaultValue = false }
extension EnvironmentValues {
    var vipiOutgoingMessage:Bool {
        get { self[OutgoingMessageKey.self] }
        set { self[OutgoingMessageKey.self] = newValue }
    }
}

enum VipiLightBubbleDepth {
    static let strokeWidth:CGFloat = 1
    static let shadowColor = Color(red:72/255.0,green:47/255.0,blue:56/255.0)
    static let shadowOpacity:Double = 0.12
    static let shadowRadius:CGFloat = 2
    static let shadowY:CGFloat = 1
}
